fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}

fn main() {
    let v1 = vec![0b10101010, 0b11110000, 1];
    let v2 = vec![0b01010101, 0b00001111, 3];

    let result = bitwise_xor(v1, v2);
    // result should be [0b11111111, 0b11111111, 2]
    assert_eq!(result, vec![255, 255, 2]);

    println!("XOR result: {:?}", result);
}